'use strict';
let sliceSelected=0,sliceAudition=null,sliceStarted=0,sliceOwner=null,sliceManual=false,padMuteMode=false;
function validSlices(p){const duration=p.data.length/sr,raw=p.slices;if(!Array.isArray(raw)||raw.length<2||raw.length>17)return [p.start*duration,p.end*duration];const values=raw.filter(Number.isFinite).map(x=>Math.max(p.start*duration,Math.min(p.end*duration,x))).sort((a,b)=>a-b);return values.length>=2?values:[p.start*duration,p.end*duration]}
function renderSlices(){if($('#sliceList').closest?.('details')&&!$('#sliceList').closest('details').open)return;const p=pads[selected],points=validSlices(p);sliceSelected=Math.max(0,Math.min(points.length-2,sliceSelected));$('#sliceList').replaceChildren();for(let i=0;i<points.length-1;i++){const button=document.createElement('button');button.className='key';button.textContent=(i+1)+' · '+(points[i+1]-points[i]).toFixed(2)+'s';button.setAttribute('aria-pressed',i===sliceSelected);button.onclick=()=>{sliceSelected=i;renderSlices();auditionSlice(i)};$('#sliceList').append(button)}$('#sliceStart').value=points[sliceSelected].toFixed(3);$('#sliceEnd').value=points[sliceSelected+1].toFixed(3)}
async function auditionSlice(index,whole=false){try{await audio();sliceAudition?.stop();const p=pads[selected],points=validSlices(p),source=ctx.createBufferSource();source.buffer=getBuffer(p,ctx);source.connect(masterBus);const start=whole?p.start*p.data.length/sr:points[index],end=whole?p.end*p.data.length/sr:points[index+1];source.start(ctx.currentTime,start,Math.max(1/sr,end-start));sliceAudition=source;sliceStarted=ctx.currentTime;sliceOwner=p;source.onended=()=>{source.disconnect();if(sliceAudition===source){sliceAudition=null;sliceManual=false;$('#tapSlice').textContent='▶ ÉCOUTER / POSER UN MARQUEUR'}}}catch(e){status(e.message)}}
function detectSlices(p,threshold){const data=p.data,start=Math.floor(p.start*data.length),end=Math.floor(p.end*data.length),hop=256,frames=[];let previous=0,peak=0;for(let i=start;i<end;i+=hop){let energy=0;for(let j=i;j<Math.min(end,i+hop);j++)energy+=data[j]*data[j]+(p.right?p.right[j]*p.right[j]:0);energy=Math.sqrt(energy/hop);const delta=Math.max(0,energy-previous);frames.push({index:i,delta});peak=Math.max(peak,delta);previous=energy}const candidates=frames.filter(f=>f.delta>peak*threshold&&f.delta>.002).sort((a,b)=>b.delta-a.delta),chosen=[start,end];for(const f of candidates)if(chosen.length<17&&chosen.every(i=>Math.abs(i-f.index)>sr*.06))chosen.push(f.index);return chosen.sort((a,b)=>a-b).map(i=>i/sr)}
$('#buildSlices').onclick=()=>{const p=pads[selected],kind=$('#chopKind').value;remember();if(kind==='threshold')p.slices=detectSlices(p,+$('#chopThreshold').value/100);else{const n=kind==='manual'?1:+kind,a=p.start*p.data.length/sr,b=p.end*p.data.length/sr;p.slices=Array.from({length:n+1},(_,i)=>a+(b-a)*i/n)}sliceSelected=0;renderSlices();changed()};
$('#tapSlice').onclick=async()=>{if(!sliceManual||!sliceAudition||sliceOwner!==pads[selected]){remember();pads[selected].slices=[pads[selected].start*pads[selected].data.length/sr,pads[selected].end*pads[selected].data.length/sr];await auditionSlice(0,true);sliceManual=true;$('#tapSlice').textContent='● POSER UN MARQUEUR';renderSlices();return}const p=pads[selected],points=validSlices(p),time=p.start*p.data.length/sr+ctx.currentTime-sliceStarted;if(points.length>=17){status('16 tranches maximum.');return}if(points.every(x=>Math.abs(x-time)>.01)&&time<points.at(-1)){p.slices=[...points,time].sort((a,b)=>a-b);renderSlices();changed()}};
$('#setSlice').onclick=()=>{const p=pads[selected],points=validSlices(p),i=sliceSelected,start=+$('#sliceStart').value,end=+$('#sliceEnd').value;if(!Number.isFinite(start)||!Number.isFinite(end)||start<(i?points[i-1]+1/sr:p.start*p.data.length/sr)||end>(i+2<points.length?points[i+2]-1/sr:p.end*p.data.length/sr)||end-start<1/sr){status('Bornes invalides : conservez l’ordre des tranches.');return}remember();points[i]=start;points[i+1]=end;p.slices=points;renderSlices();changed()};
$('#splitSlice').onclick=()=>{const p=pads[selected],points=validSlices(p);if(points.length>=17){status('16 tranches maximum.');return}remember();points.splice(sliceSelected+1,0,(points[sliceSelected]+points[sliceSelected+1])/2);p.slices=points;renderSlices();changed()};
$('#mergeSlice').onclick=()=>{if(!sliceSelected)return;remember();const p=pads[selected],points=validSlices(p);points.splice(sliceSelected,1);p.slices=points;sliceSelected--;renderSlices();changed()};
function extractSlices(all){const p=pads[selected],points=validSlices(p),indices=all?Array.from({length:points.length-1},(_,i)=>i):[sliceSelected],targets=pads.map((p,i)=>p.data.length===1?i:-1).filter(i=>i>=0);if(targets.length<indices.length)throw Error('Pas assez de pads vides.');const added=indices.reduce((n,i)=>n+Math.max(1,Math.round((points[i+1]-points[i])*sr))*(p.right?2:1),0);if(pads.reduce((n,p)=>n+p.data.length*(p.right?2:1),0)+added>sr*240)throw Error('Mémoire audio pleine.');remember();indices.forEach((slice,j)=>{const from=Math.floor(points[slice]*sr),to=Math.max(from+1,Math.floor(points[slice+1]*sr));pads[targets[j]]={...createPad(16),...cleanPadSettings(p),data:p.data.slice(from,to),right:p.right?p.right.slice(from,to):null,start:0,end:1,loopStart:0,name:'SLICE '+(slice+1),pitch:p.pitch,volume:p.volume,filter:p.filter,automation:{},events:{}}});render();changed();status(indices.length+' tranches extraites vers des pads vides. Original conservé.')}
$('#extractSlice').onclick=()=>{try{extractSlices(false)}catch(e){status(e.message)}};$('#distributeSlices').onclick=()=>{try{extractSlices(true)}catch(e){status(e.message)}};
$('#muteMode').onclick=()=>{padMuteMode=!padMuteMode;$('#muteMode').classList.toggle('active',padMuteMode);$('#muteMode').setAttribute('aria-pressed',padMuteMode);status(padMuteMode?'Mode Mute : touchez les pads pour les rendre muets ou les réactiver.':'Les pads jouent les sons.')};
renderSlices();

$('#sliceList').closest?.('details')?.addEventListener('toggle',renderSlices);
